def minAbsDifference(nums: list[int], goal: int) -> int:
    from bisect import bisect_left
    n = len(nums)
    mid = n // 2
    left, right = nums[:mid], nums[mid:]
    def get_sums(arr):
        sums = {0}
        for x in arr:
            sums |= {s + x for s in sums}
        return sorted(list(sums))
    s1 = get_sums(left)
    s2 = get_sums(right)
    ans = abs(goal)
    for x in s1:
        target = goal - x
        idx = bisect_left(s2, target)
        if idx < len(s2):
            ans = min(ans, abs(x + s2[idx] - goal))
        if idx > 0:
            ans = min(ans, abs(x + s2[idx - 1] - goal))
    return ans

